import pandas as pd
from collections import Counter, defaultdict
from typing import List, Tuple

from solver import Algorithm


class Evolved(Algorithm):
    """Bounded character-Trie optimizer using global, conditional, and
    prototype-aligned atomic-column permutations."""

    def __init__(self, df: pd.DataFrame = None):
        """Store the optional frame and lightweight shape metadata."""
        self.df = df
        self.num_rows = 0
        self.num_cols = 0

    @staticmethod
    def _text(value) -> str:
        """Serialize one scalar exactly as scoring does, mapping missing values to ''."""
        try:
            missing = pd.isna(value)
            if isinstance(missing, bool) and missing:
                return ""
        except Exception:
            pass
        return str(value)

    @staticmethod
    def _lcp(a: str, b: str) -> int:
        """Return the exact common-prefix length using binary-search slicing."""
        limit = min(len(a), len(b))
        if limit == 0 or a[0] != b[0]:
            return 0
        lo, hi = 1, limit
        while lo < hi:
            mid = (lo + hi + 1) // 2
            if a[:mid] == b[:mid]:
                lo = mid
            else:
                hi = mid - 1
        return lo

    @classmethod
    def _reuse(cls, strings: List[str]) -> int:
        """Compute ideal character-Trie reuse from sorted adjacent row strings."""
        if len(strings) < 2:
            return 0
        ordered = sorted(strings)
        total = 0
        previous = ordered[0]
        for current in ordered[1:]:
            if current == previous:
                total += len(current)
            else:
                total += cls._lcp(previous, current)
            previous = current
        return total

    @staticmethod
    def _merge(columns, order, col_merge):
        """Return a full column order with requested groups kept contiguous."""
        if not col_merge:
            return list(order)

        position = {c: i for i, c in enumerate(order)}
        claimed = set()
        grouped = {}

        for request in col_merge or []:
            members = [c for c in order if c in request and c not in claimed]
            if not members:
                continue
            members.sort(key=position.__getitem__)
            for c in members:
                grouped[c] = members
                claimed.add(c)

        result = []
        emitted = set()
        for c in order:
            if c in emitted:
                continue
            group = grouped.get(c)
            if group is None:
                result.append(c)
                emitted.add(c)
            else:
                result.extend(group)
                emitted.update(group)
        return result

    @staticmethod
    def _units(columns, col_merge):
        """Build atomic blocks whose internal order satisfies all merge requests."""
        columns = list(columns)
        base = Evolved._merge(columns, columns, col_merge)
        lookup = {c: i for i, c in enumerate(columns)}
        used = set()
        units = []

        for name in base:
            if name in used:
                continue
            members = None
            for request in col_merge or []:
                if name in request:
                    members = [c for c in base if c in request]
                    break
            if members is None:
                members = [name]

            members = [lookup[c] for c in members if c not in used]
            if members:
                units.append(members)
                used.update(columns[j] for j in members)

        for j, c in enumerate(columns):
            if c not in used:
                units.append([j])
        return units

    @staticmethod
    def _block_text(text, units):
        """Precompute each row's serialized value for every atomic block."""
        return [
            ["".join(text[r][j] for j in unit) for unit in units]
            for r in range(len(text))
        ]

    @staticmethod
    def _expand(unit_order, units):
        """Expand an atomic-block permutation into source-column indices."""
        return [j for u in unit_order for j in units[u]]

    @staticmethod
    def _serial(text, orders):
        """Serialize every row using its row-specific source-column order."""
        return [
            "".join(text[r][j] for j in orders[r])
            for r in range(len(orders))
        ]

    def _rank_units(self, blocks):
        """Rank blocks by length-weighted pair repetition with stable ties."""
        if not blocks:
            return []
        k = len(blocks[0])
        scores = []
        for u in range(k):
            counts = Counter(row[u] for row in blocks)
            pair = sum(
                len(value) * count * (count - 1)
                for value, count in counts.items()
            )
            repeat = sum(
                len(value) * (count - 1)
                for value, count in counts.items()
            )
            scores.append((pair, repeat, u))
        return [
            u for _, _, u in sorted(
                scores, key=lambda x: (-x[0], -x[1], x[2])
            )
        ]

    def _conditional(self, blocks, ranked):
        """Construct a bounded conditional prefix partition over repeated blocks."""
        n = len(blocks)
        result = [None] * n
        stack = [(list(range(n)), list(ranked), 0)]
        nodes = 0

        while stack and nodes < 384:
            rows, remaining, depth = stack.pop()
            nodes += 1

            if len(rows) < 2 or depth >= 8 or not remaining:
                for r in rows:
                    result[r] = remaining[:]
                continue

            best_unit = None
            best_score = 0
            best_groups = None

            for u in remaining[:20]:
                groups = defaultdict(list)
                for r in rows:
                    groups[blocks[r][u]].append(r)

                score = sum(
                    len(value) * len(group) * (len(group) - 1)
                    for value, group in groups.items()
                    if len(group) > 1
                )
                if score > best_score or (
                    score == best_score
                    and score > 0
                    and (best_unit is None or u < best_unit)
                ):
                    best_unit = u
                    best_score = score
                    best_groups = groups

            if best_unit is None or best_score <= 0:
                for r in rows:
                    result[r] = remaining[:]
                continue

            rest = [u for u in remaining if u != best_unit]
            children = sorted(
                best_groups.values(),
                key=lambda group: (-len(group), min(group)),
            )
            for child in reversed(children):
                stack.append((child, rest, depth + 1))

        fallback = ranked[:]
        for r in range(n):
            if result[r] is None:
                result[r] = fallback[:]
        return result

    def _prototype(self, blocks, ranked):
        """Align rows in repeated anchor groups to lexicographic prototypes.

        At each step the best available block is selected by its exact LCP
        against the unmatched prototype suffix.  Once a block partially
        mismatches, the remaining blocks use the global ranked tail.
        """
        n = len(blocks)
        k = len(ranked)
        result = [ranked[:] for _ in range(n)]
        if n == 0 or k == 0:
            return result

        anchor_info = []
        for u in ranked[:min(12, k)]:
            counts = Counter(row[u] for row in blocks)
            pair_mass = sum(
                len(value) * count * (count - 1)
                for value, count in counts.items()
            )
            anchor_info.append((pair_mass, u))

        anchor_info.sort(key=lambda x: (-x[0], x[1]))
        anchors = [u for mass, u in anchor_info if mass > 0]

        groups = defaultdict(list)
        if anchors:
            anchor = anchors[0]
            for r in range(n):
                groups[blocks[r][anchor]].append(r)
        else:
            groups[None] = list(range(n))

        for rows in list(groups.values())[:128]:
            if len(rows) < 2:
                continue

            prototypes = sorted(
                rows,
                key=lambda r: "".join(blocks[r][u] for u in ranked),
            )
            prototype = prototypes[0]
            target = "".join(blocks[prototype][u] for u in ranked)

            for r in rows:
                available = set(ranked)
                chosen = []
                suffix = target
                aligned = True

                while available and suffix and aligned:
                    candidates = [
                        u for u in ranked if u in available
                    ][:16]
                    if not candidates:
                        break

                    best_u = candidates[0]
                    best_key = None
                    best_match = 0

                    for u in candidates:
                        value = blocks[r][u]
                        match = self._lcp(value, suffix)
                        # Repetition mass is approximated locally by value
                        # length; exact group repetition is already supplied
                        # by the anchor partition.
                        key = (match, len(value), -u)
                        if best_key is None or key > best_key:
                            best_key = key
                            best_u = u
                            best_match = match

                    if best_match <= 0:
                        break

                    chosen.append(best_u)
                    available.remove(best_u)
                    value = blocks[r][best_u]

                    if best_match == len(value):
                        suffix = suffix[len(value):]
                    else:
                        # A partial-field prefix is useful, but no later block
                        # can continue the prototype string reliably.
                        aligned = False

                chosen.extend(u for u in ranked if u in available)
                result[r] = chosen

        return result

    def reorder(
        self,
        df: pd.DataFrame,
        early_stop: int = 0,
        row_stop: int = None,
        col_stop: int = None,
        col_merge=[],
        one_way_dep=[],
        distinct_value_threshold=0.8,
        parallel=True,
    ) -> Tuple[pd.DataFrame, List[List[str]]]:
        """Evaluate global, conditional, and prototype candidates exactly."""
        self.df = df
        self.num_rows, self.num_cols = df.shape
        n, m = df.shape
        columns = list(df.columns)

        if n == 0 or m == 0:
            return df.copy(), [[] for _ in range(n)]

        raw = df.to_numpy(dtype=object, copy=True)
        text = [
            [self._text(raw[r, j]) for j in range(m)]
            for r in range(n)
        ]

        units = self._units(columns, col_merge)
        blocks = self._block_text(text, units)
        ranked = self._rank_units(blocks)

        unit_candidates = [
            [ranked[:] for _ in range(n)],
            self._conditional(blocks, ranked),
            self._prototype(blocks, ranked),
        ]

        candidates = []
        for unit_orders in unit_candidates:
            source_orders = [
                self._expand(order, units)
                for order in unit_orders
            ]
            serial = self._serial(text, source_orders)
            candidates.append((
                self._reuse(serial),
                source_orders,
                serial,
            ))

        _, best_orders, best_serial = max(
            candidates,
            key=lambda item: item[0],
        )

        row_order = sorted(range(n), key=lambda r: best_serial[r])
        output = [
            [raw[r, j] for j in best_orders[r]]
            for r in row_order
        ]
        orderings = [
            [columns[j] for j in best_orders[r]]
            for r in row_order
        ]

        result = pd.DataFrame(
            output,
            columns=columns,
            index=df.index.take(row_order),
            dtype=object,
        )
        return result, orderings

